@dataclass
class Port:
    """One port of a hardware module."""

    name: str
    port_type: Optional[Type] = None
    direction: Direction = Direction.INPUT

    def __post_init__(self) -> None:
        self.direction = Direction.parse(self.direction)

    @property
    def is_input(self) -> bool:
        return self.direction is Direction.INPUT

    @property
    def is_output(self) -> bool:
        return self.direction is Direction.OUTPUT

    @property
    def is_inout(self) -> bool:
        return self.direction is Direction.INOUT

    def bit_width(self) -> int:
        return bit_width_of(self.port_type)

    def __repr__(self) -> str:
        return f"Port({self.direction.value} {self.name}: {self.port_type})"


