class Block:
    """An ordered list of operations with SSA arguments."""

    def __init__(
        self,
        arg_types: Optional[Sequence[Type]] = None,
        label: Optional[str] = None,
        arg_names: Optional[Sequence[Optional[str]]] = None,
    ) -> None:
        self.label = label
        self.parent: Optional["Region"] = None
        self.arguments: List[BlockArgument] = []
        self.operations: List[Operation] = []
        names = list(arg_names or ())
        for index, atype in enumerate(arg_types or ()):
            aname = names[index] if index < len(names) else None
            self.add_argument(atype, aname)

    # -- arguments --------------------------------------------------------
    def add_argument(self, type: Type, name: Optional[str] = None) -> BlockArgument:
        arg = BlockArgument(self, len(self.arguments), type, name)
        self.arguments.append(arg)
        return arg

    @property
    def num_arguments(self) -> int:
        return len(self.arguments)

    def argument(self, index: int) -> BlockArgument:
        return self.arguments[index]

    @property
    def argument_types(self) -> List[Type]:
        return [a.type for a in self.arguments]

    # -- operation list ---------------------------------------------------
    def append(self, op: Operation) -> Operation:
        op.parent = self
        self.operations.append(op)
        return op

    add = append

    def push_front(self, op: Operation) -> Operation:
        op.parent = self
        self.operations.insert(0, op)
        return op

    def insert(self, index: int, op: Operation) -> Operation:
        op.parent = self
        self.operations.insert(index, op)
        return op

    def insert_before(self, existing: Operation, op: Operation) -> Operation:
        return self.insert(self.operations.index(existing), op)

    def insert_after(self, existing: Operation, op: Operation) -> Operation:
        return self.insert(self.operations.index(existing) + 1, op)

    def remove(self, op: Operation) -> None:
        try:
            self.operations.remove(op)
        except ValueError:
            return
        op.parent = None

    def erase_all_operations(self) -> None:
        for op in reversed(list(self.operations)):
            op.erase()

    @property
    def terminator(self) -> Optional[Operation]:
        if self.operations and self.operations[-1].is_terminator:
            return self.operations[-1]
        return None

    @property
    def num_operations(self) -> int:
        return len(self.operations)

    @property
    def successors(self) -> List["Block"]:
        term = self.terminator
        return list(term.successors) if term is not None else []

    @property
    def predecessors(self) -> List["Block"]:
        preds: List["Block"] = []
        if self.parent is None:
            return preds
        for block in self.parent.blocks:
            if self in block.successors and block not in preds:
                preds.append(block)
        return preds

    # -- traversal --------------------------------------------------------
    def walk(
        self,
        callback: Callable[[Operation], Any],
        order: WalkOrder = WalkOrder.PRE_ORDER,
    ) -> None:
        for op in list(self.operations):
            op.walk(callback, order)

    def clone(self, value_map: Optional[Dict[Value, Value]] = None) -> "Block":
        value_map = {} if value_map is None else value_map
        clone = Block(arg_types=self.argument_types, label=self.label,
                      arg_names=[a.name for a in self.arguments])
        for old, new in zip(self.arguments, clone.arguments):
            value_map[old] = new
        for op in self.operations:
            clone.append(op.clone(value_map))
        return clone

    # -- verification -----------------------------------------------------
    def verify(self) -> List[str]:
        errors: List[str] = []
        for index, op in enumerate(self.operations):
            if op.is_terminator and index != len(self.operations) - 1:
                errors.append(
                    f"terminator '{op.name}' must be the last operation in its block"
                )
            errors.extend(op.verify())
        return errors

    def __iter__(self) -> Iterator[Operation]:
        return iter(self.operations)

    def __len__(self) -> int:
        return len(self.operations)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Block {self.label or '^entry'} ops={len(self.operations)}>"


