class Operation:
    """A generic MLIR operation.

    Subclasses in the dialect modules add sugar (accessors, folders, verifiers)
    but the storage lives here so that generic passes work on anything.
    """

    #: Overridden by subclasses via :meth:`operation_name`.
    OPERATION_NAME: Optional[str] = None
    TRAITS: Tuple[Trait, ...] = ()

    def __init__(
        self,
        name: Optional[str] = None,
        operands: Optional[Sequence[Value]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        successors: Optional[Sequence["Block"]] = None,
        regions: Optional[Sequence["Region"]] = None,
        num_regions: int = 0,
        location: Optional[Location] = None,
        result_names: Optional[Sequence[Optional[str]]] = None,
    ) -> None:
        self._name = name or self.operation_name()
        if self._name is None:
            raise ValueError("operation requires a name")
        self.uid = next(_OP_IDS)
        self.location = location or Location.unknown()
        self.attributes: Dict[str, Attribute] = dict(attributes or {})
        self.parent: Optional["Block"] = None

        self._operands: List[OpOperand] = []
        for value in operands or ():
            self.add_operand(value)

        names = list(result_names or ())
        self._results: List[OpResult] = []
        for index, rtype in enumerate(result_types or ()):
            rname = names[index] if index < len(names) else None
            self._results.append(OpResult(self, index, rtype, rname))

        self.successors: List["Block"] = list(successors or ())
        self.regions: List["Region"] = []
        for region in regions or ():
            self.add_region(region)
        for _ in range(num_regions):
            self.add_region(Region())

    # -- identity ---------------------------------------------------------
    @classmethod
    def operation_name(cls) -> Optional[str]:
        return cls.OPERATION_NAME

    @property
    def name(self) -> str:
        return self._name

    @property
    def op_name(self) -> str:
        return self._name

    @property
    def dialect_name(self) -> str:
        return self._name.split(".")[0] if "." in self._name else ""

    @property
    def mnemonic(self) -> str:
        return name in self.attributes

    def attr_value(self, name: str, default: Any = None) -> Any:
        attr = self.attributes.get(name)
        return default if attr is None else attr.value

    # -- regions ----------------------------------------------------------
    def add_region(self, region: Optional["Region"] = None) -> "Region":
        region = region if region is not None else Region()
        region.parent = self
        self.regions.append(region)
        return region

    @property
    def num_regions(self) -> int:
        return len(self.regions)

    def region(self, index: int = 0) -> "Region":
        return self.regions[index]

    @property
    def body(self) -> "Region":
        if not self.regions:
            self.add_region(Region())
        return self.regions[0]

    # -- position ---------------------------------------------------------
    @property
    def parent_block(self) -> Optional["Block"]:
        return self.parent

    @property
    def parent_region(self) -> Optional["Region"]:
        return self.parent.parent if self.parent is not None else None

    @property
    def parent_op(self) -> Optional["Operation"]:
        region = self.parent_region
        return region.parent if region is not None else None

    def get_parent_of_name(self, name: str) -> Optional["Operation"]:
        Returns a list of Python constants (one per result) when the operation
        can be folded, ``None`` otherwise.  Overridden by dialect operations.
        """
        return None

    # -- parser hooks -----------------------------------------------------
    @classmethod
    def build_parsed(cls, **kwargs: Any) -> "Operation":
        """Create an instance of ``cls`` from generic parser output.

        Dialect operations have bespoke constructors, so the parser cannot call
        them uniformly.  This bypasses the subclass ``__init__`` and populates
        the generic storage directly, which keeps the concrete class (and hence
        its traits, folders and accessors) while letting the parser stay
        dialect-agnostic.  Subclasses with extra instance state override this.
        """
        op = cls.__new__(cls)
        Operation.__init__(op, **kwargs)
        return op

    @classmethod
    def result_types_from_trailing(
        cls, trailing_types: Sequence[Type], num_results: int
    ) -> List[Type]:
        """Map a trailing ``: type`` clause onto result types.

        The default rule is MLIR's: the trailing type describes the results.
        Comparison-like operations override this because their trailing type
        describes the *operands* while the result is always ``i1``.
        """
        if num_results == 0:
            return []
        if not trailing_types:
            return []
        if len(trailing_types) == num_results:
            return list(trailing_types)
        return [trailing_types[-1]] * num_results

    # -- verification -----------------------------------------------------
    def verify(self) -> List[str]:
        errors: List[str] = []
        if self.has_trait(Trait.SAME_OPERANDS_AND_RESULT_TYPE):
            types = self.result_types + [
                v.type for v in self.operands if isinstance(v, Value)
            ]
            if types and any(t != types[0] for t in types):
                errors.append(
                    f"'{self.name}' requires all operands and results to have the "
                    f"same type, got {[str(t) for t in types]}"
                )
        errors.extend(self.verify_op())
        for region in self.regions:
            errors.extend(region.verify())
        return errors

    def verify_op(self) -> List[str]:
        """Hook for op-specific verification."""
        return []

    # -- printing ---------------------------------------------------------
    def __str__(self) -> str:
        from .printer import print_op

        return print_op(self)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Operation {self._name} operands={self.num_operands} results={self.num_results}>"


