    def get_operand(self, index: int) -> Any:
        operands = self.operands
        if index < 0 or index >= len(operands):
            raise IndexError(f"operand index {index} out of range")
        return operands[index]

    def read_operand(self, env: SignalEnv, index: int, default: int = 0) -> int:
        """Read operand ``index`` out of ``env``."""
        if self._symbolic_operands is not None:
            if index >= len(self._symbolic_operands):
                return default
            key = self._symbolic_operands[index]
            return int(env.get(key, default))
        values = self.ssa_operands
        if index >= len(values):
            return default
        value = values[index]
        if value in env:
            return int(env[value])
        if value.name is not None and value.name in env:
            return int(env[value.name])
        return default

    def read_operands(self, env: SignalEnv) -> List[int]:
        return [self.read_operand(env, i) for i in range(self.num_operands)]

    # -- widths -----------------------------------------------------------
    @property
    def width(self) -> int:
        if self.num_results:
            return bit_width_of(Operation.results.fget(self)[0].type)  # type: ignore[attr-defined]
