class SSANameState:
    """Assigns stable ``%0``/``^bb0`` names while printing."""

    def __init__(self, preserve_names: bool = True) -> None:
        self.preserve_names = preserve_names
        self._value_names: Dict[int, str] = {}
        self._block_names: Dict[int, str] = {}
        self._next_value = 0
    # -- public API -------------------------------------------------------
    def print_operation(self, op: Operation) -> str:
        self._output = io.StringIO()
        self._indent_level = 0
        self._print_op(op)
        return self._output.getvalue().rstrip("\n")

    print_op = print_operation

    def print_module(self, module: Operation) -> str:
        return self.print_operation(module)

    # -- emit helpers -----------------------------------------------------
    def _write(self, text: str) -> None:
        self._output.write(text)

    def _write_line(self, text: str) -> None:
        self._output.write(" " * (self._indent_level * self._indent_size))
        self._output.write(text)
        self._output.write("\n")

    @property
    def _indent(self) -> str:
        return " " * (self._indent_level * self._indent_size)

    # -- operation printing -----------------------------------------------
    def _print_op(self, op: Operation) -> None:
        # Operations that are isolated from above (functions, hardware modules)
        # open a fresh SSA namespace, exactly as MLIR does, so ``%sum`` can be
        # reused in two sibling functions.
