        if op.has_trait(Trait.ISOLATED_FROM_ABOVE) and op.name != "builtin.module":
            saved_state = self._name_state
            self._name_state = SSANameState(preserve_names=saved_state.preserve_names)
        try:
            header = self._format_op_header(op)
            if op.regions and any(r.blocks for r in op.regions):
                self._write_line(header + " {")
                for region in op.regions:
                    self._print_region(region)
                self._write_line("}")
            else:
                self._write_line(header)
        finally:
            if saved_state is not None:
                self._name_state = saved_state

    def _format_op_header(self, op: Operation) -> str:
        if op.name in ("builtin.module",):
            sym = op.attributes.get("sym_name")
            return "module" + (f" @{sym.value}" if sym is not None else "")
        if op.name in ("func.func", "builtin.func"):
            return self._format_function_header(op)
        if op.name in ("hw.module", "hw.module.extern", "firrtl.module"):
            return self._format_hw_module_header(op)
        return self._format_generic_op(op)

    def _format_function_header(self, op: Operation) -> str:
        sym = op.attributes.get("sym_name")
        name = f"@{sym.value}" if sym is not None else "@unknown"
        block = op.regions[0].entry_block if op.regions else None
        args: List[str] = []
        if block is not None:
            for arg in block.arguments:
                args.append(f"{self._name_state.get_value_name(arg)}: {arg.type}")
        else:
            ftype = self._function_type(op)
            if ftype is not None:
                args = [str(t) for t in ftype.inputs]
        ftype = self._function_type(op)
        results = list(ftype.results) if ftype is not None else []
        text = f"{op.name} {name}({', '.join(args)})"
        if results:
            if len(results) == 1:
                text += f" -> {results[0]}"
            else:
                text += " -> (" + ", ".join(str(t) for t in results) + ")"
        return text

    def _format_hw_module_header(self, op: Operation) -> str:
        sym = op.attributes.get("sym_name")
        name = f"@{sym.value}" if sym is not None else "@unknown"
        port_names = op.attributes.get("port_names")
        port_dirs = op.attributes.get("port_directions")
        ftype = self._function_type(op)
        entries: List[str] = []
        if isinstance(port_names, ArrayAttr) and isinstance(port_dirs, ArrayAttr):
            block = op.regions[0].entry_block if op.regions else None
            input_index = 0
            output_types = list(ftype.results) if ftype is not None else []
