# The accessors below deliberately match nested operations by mnemonic as well
# as by class, because :meth:`~src.mlir.ir.Operation.clone` rebuilds children as
# plain :class:`~src.mlir.ir.Operation` instances.  Everything that *executes* a
# machine therefore has to go through these helpers rather than calling
# ``StateOp`` / ``TransitionOp`` methods directly, or a cloned - or hand-built
# generic - body raises ``AttributeError``.


def _nested_ops(op: Operation) -> List[Operation]:
    """Every operation in ``op``'s regions, flattened, in textual order."""
    return [child for region in op.regions for child in region.operations]


def _transitions_in(state: Operation) -> List[Operation]:
    """The ``fsm.transition`` operations owned by ``state``."""
    transitions = getattr(state, "transitions", None)
    if transitions is not None:
        return list(transitions)
    return [
        child
        for child in _nested_ops(state)
        if child.name == TransitionOp.OPERATION_NAME
    ]


def _transition_target(transition: Operation) -> str:
    """The state name ``transition`` goes to (``""`` when it has no target)."""
    return _string_attr(transition, "target", "next_state", "sym_name")


def _transition_enabled(transition: Operation, env: SignalEnv) -> bool:
    """Is ``transition`` taken under ``env``?  Generic ops are unconditional."""
    is_enabled = getattr(transition, "is_enabled", None)
    if callable(is_enabled):
        return bool(is_enabled(env))
    return True


def _next_state_of(state: Operation, env: SignalEnv) -> Optional[str]:
    """The target of ``state``'s first enabled transition, ``None`` if none."""
    for transition in _transitions_in(state):
        if _transition_enabled(transition, env):
            target = _transition_target(transition)
            if target:
                return target
    return None


def _output_in(state: Operation) -> Optional[Operation]:
    """The ``fsm.output`` terminator of ``state``, if it has one."""
    output = getattr(state, "output_op", None)
    if output is not None:
        return output
    for child in reversed(_nested_ops(state)):
        if child.name == FSMOutputOp.OPERATION_NAME:
            return child
    return None


def _read_operands(op: Operation, env: SignalEnv) -> List[int]:
    """``op``'s operand values, looked up the way :class:`HWOp` does it."""
    read = getattr(op, "read_operands", None)
    if callable(read):
        return read(env)
    values: List[int] = []
    for operand in op.operands:
        if isinstance(operand, str):
            values.append(int(env.get(operand, 0)))
        elif operand in env:
            values.append(int(env[operand]))
        elif getattr(operand, "name", None) in env:
            values.append(int(env[operand.name]))
        else:
            values.append(0)
    return values


def _outputs_of(state: Operation, env: SignalEnv) -> List[int]:
    """What ``state`` drives through its ``fsm.output``, ``[]`` without one."""
    output = _output_in(state)
    if output is None:
        return []
    return _read_operands(output, env)

